#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Object,
}

impl DType {
    /// Returns the precedence value of this dtype.
    fn precedence(&self) -> u8 {
        use DType::*;
        match self {
            Bool => 0,
            Int8 => 1,
            Int16 => 2,
            Int32 => 3,
            Int64 => 4,
            UInt8 => 5,
            UInt16 => 6,
            UInt32 => 7,
            UInt64 => 8,
            Float32 => 9,
            Float64 => 10,
            Complex64 => 11,
            Complex128 => 12,
            Object => 13,
        }
    }

    /// Returns the kind character for the dtype (e.g., 'b' for boolean, 'i' for signed int, etc.)
    fn kind(&self) -> char {
        use DType::*;
        match self {
            Bool => 'b',       // boolean
            Int8 | Int16 | Int32 | Int64 => 'i',   // signed int
            UInt8 | UInt16 | UInt32 | UInt64 => 'u', // unsigned int
            Float32 | Float64 => 'f',               // float
            Complex64 | Complex128 => 'c',          // complex
            Object => 'O',                          // object
        }
    }
}

/// Given a non-empty collection of dtypes, returns the dtype with maximum precedence
/// (must be an element of the input vector).
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Safe unwrap since input vec is non-empty as per problem statement
    types.into_iter()
         .max_by_key(|dt| dt.precedence())
         .unwrap()
}

/// Given two collections (array_types and scalar_types),
/// returns an Option<DType> representing the common dtype according to the specified rules:
/// - If only array_types is non-empty, return max precedence dtype from array_types.
/// - If only scalar_types is non-empty, return max precedence dtype from scalar_types.
/// - If both non-empty:
///     . find max dtype from each collection
///     . if kinds match, return max from array_types
///     . else return max from scalar_types
///
/// If both empty, returns None.
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let has_array = !array_types.is_empty();
    let has_scalar = !scalar_types.is_empty();

    match (has_array, has_scalar) {
        (false, false) => None, // both empty => no common type

        (true, false) => Some(find_max_precedence_type(array_types)),

        (false, true) => Some(find_max_precedence_type(scalar_types)),

        (true, true) => {
            let arr_max = find_max_precedence_type(array_types);
            let scal_max = find_max_precedence_type(scalar_types);

            if arr_max.kind() == scal_max.kind() {
                Some(arr_max)
            } else {
                Some(scal_max)
            }
        }
    }
}